using CargoWise.EntityFramework.Testing;
using Enterprise.TransportConsignment.Business;
using Enterprise.TransportConsignment.DataTransfer.Universal.Helpers;
using Enterprise.UniversalDataBuss.DataObjects;
using Enterprise.UniversalDataBuss.DataObjects.Core;
using Enterprise.UniversalDataBuss.DataObjects.Universal;
using UniversalShipment = Enterprise.UniversalDataBuss.DataObjects.Universal.Shipment;

namespace Enterprise.TransportConsignment.DataTransfer.Test
{
	public class XmlHelperTest : TestCaseWithFactory
	{
		#region TestSerializeUniversalResponse
		public void TestSerializeUniversalResponse()
		{
			var (shipment, status) = XmlHelper.DeserializeUniversalShipment(ResponseXml);
			AssertEquals("PRS", status);
			AssertEquals(shipment.AttachedDocumentCollection.Count, 1);
			AssertEquals(shipment.AttachedDocumentCollection[0].FileName, "labels.pdf");
			AssertNotNull(shipment.AttachedDocumentCollection[0].ImageData);
			shipment.Dispose();
		}
		#endregion
		#region TestSerializeUniversalTransaction
		public void TestSerializeUniversalTransaction()
		{
			UniversalInterchangeHelper universalInterchangeHelper = new UniversalInterchangeHelper();
			universalInterchangeHelper.universalShipment = new UniversalShipment(DefaultDataObjectWriterStrategy.TestInstance);
			universalInterchangeHelper.universalShipment.WayBillNumber = "1";
			var packageData = new PackingLine(DefaultDataObjectWriterStrategy.TestInstance) { PackQty = 1, ReferenceNumber = "ABC", Weight = 150m };
			universalInterchangeHelper.universalShipment.SetPackingLineCollection(() => new DataObjectList<PackingLine>(new[] { packageData })
			{
				Content = CollectionContent.Complete
			});

			var universalXml = universalInterchangeHelper.GetUniversalInterchangeXml();
#if NETFRAMEWORK
			var expectedXml = "<?xmlversion=\"1.0\"encoding=\"utf-8\"?><UniversalInterchangexmlns:xsd=\"http://www.w3.org/2001/XMLSchema\"xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"xmlns=\"http://www.cargowise.com/Schemas/Universal/2011/11\"><Header><SenderID/><RecipientID/><DeliveryMetadata/></Header><Body><UniversalShipmentxmlns=\"http://www.cargowise.com/Schemas/Universal/2011/11\"version=\"1.1\"><Shipment><WayBillNumber>1</WayBillNumber><PackingLineCollectionContent=\"Complete\"><PackingLine><PackQty>1</PackQty><ReferenceNumber>ABC</ReferenceNumber><Weight>150</Weight></PackingLine></PackingLineCollection></Shipment></UniversalShipment></Body></UniversalInterchange>";
#elif NET
			var expectedXml = "<?xmlversion=\"1.0\"encoding=\"utf-8\"?><UniversalInterchangexmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\"xmlns=\"http://www.cargowise.com/Schemas/Universal/2011/11\"><Header><SenderID/><RecipientID/><DeliveryMetadata/></Header><Body><UniversalShipmentxmlns=\"http://www.cargowise.com/Schemas/Universal/2011/11\"version=\"1.1\"><Shipment><WayBillNumber>1</WayBillNumber><PackingLineCollectionContent=\"Complete\"><PackingLine><PackQty>1</PackQty><ReferenceNumber>ABC</ReferenceNumber><Weight>150</Weight></PackingLine></PackingLineCollection></Shipment></UniversalShipment></Body></UniversalInterchange>";
#endif
			AssertEquals(expectedXml.Replace(" ", "").Replace("\n", "").Replace("\r", ""), universalXml.Replace(" ", "").Replace("\n", "").Replace("\r", ""));
		}
		#endregion

